package api

import (
	"bytes"
	"encoding/json"
	"io"
	"math"
	"net/http"
	"regexp"
	"strconv"
	"strings"
	"time"

	"github.com/gin-gonic/gin"
)

// Parameter names accepted on every entry point. The first name of each list
// is the canonical name used in responses.
var (
	serviceNameKeys = []string{"service_name", "serviceName", "service"}
	instanceIDKeys  = []string{"instance_id", "instanceId", "instance", "id"}
	addressKeys     = []string{"address", "addr", "host", "endpoint"}
	portKeys        = []string{"port"}
	healthKeys      = []string{"health", "healthy", "status", "state"}
	weightKeys      = []string{"weight"}
	heartbeatKeys   = []string{"heartbeat_at", "heartbeatAt", "heartbeat", "heartbeat_time", "heartbeatTime", "last_heartbeat"}
	evaluateAtKeys  = []string{"evaluate_at", "evaluateAt", "at", "now", "evaluate_time", "evaluateTime"}
	timeoutKeys     = []string{"heartbeat_timeout", "heartbeatTimeout", "timeout", "timeout_seconds", "timeoutSeconds", "heartbeat_timeout_seconds"}
)

type apiError struct {
	status  int
	code    string
	message string
}

func errInvalidParameter(message string) *apiError {
	return &apiError{http.StatusBadRequest, "invalid_parameter", message}
}

func errInstanceNotFound() *apiError {
	return &apiError{http.StatusNotFound, "instance_not_found", "service instance not found"}
}

func errStorageUnavailable() *apiError {
	return &apiError{http.StatusServiceUnavailable, "storage_unavailable", "database is not available"}
}

func writeError(c *gin.Context, e *apiError) {
	c.JSON(e.status, gin.H{"error": gin.H{"code": e.code, "message": e.message}})
}

// trimJSONWhitespace removes only the JSON whitespace characters U+0020
// space, U+0009 tab, U+000A line feed and U+000D carriage return from both
// ends. bytes.TrimSpace must not be used here: it trims every Unicode
// whitespace, so a body of NBSP (U+00A0), em space (U+2003), ideographic
// space (U+3000), U+000B or U+000C would be mistaken for an empty body and
// silently fall back to query parameters even though JSON parsers reject
// those bytes outside a string. Whitespace that is legal only inside JSON
// strings is untouched there, since this scans only the document framing.
func trimJSONWhitespace(raw []byte) []byte {
	start, end := 0, len(raw)
	for start < end && isJSONWhitespace(raw[start]) {
		start++
	}
	for end > start && isJSONWhitespace(raw[end-1]) {
		end--
	}
	return raw[start:end]
}

func isJSONWhitespace(b byte) bool {
	return b == ' ' || b == '\t' || b == '\n' || b == '\r'
}

// paramBag merges JSON body fields and query parameters, keeping route path
// parameters separate. Body fields win over query parameters; path
// parameters are read through locateText and win over both of them.
type paramBag struct {
	values map[string]any
	path   map[string]any
}

func buildParamBag(c *gin.Context) (*paramBag, *apiError) {
	bag := &paramBag{
		values: make(map[string]any),
		path:   make(map[string]any),
	}

	for key, values := range c.Request.URL.Query() {
		if len(values) > 0 {
			bag.values[key] = values[0]
		}
	}

	// A non-empty body must be exactly one JSON object surrounded only by
	// JSON whitespace: a null, array or other bare value, a truncated object,
	// a second JSON value or a stray closing bracket are all parameter
	// errors, even when the query parameters alone would complete the
	// request. An empty body, or one made only of the four JSON whitespace
	// bytes (space, tab, line feed, carriage return), carries no fields, so
	// the query-parameter lookup rules still apply; other Unicode whitespace
	// such as NBSP is not JSON whitespace and is rejected. An empty {}
	// object merges with query parameters like any other (empty) field set.
	if c.Request.Body != nil {
		body, present, apiErr := readOptionalObjectBody(c)
		if apiErr != nil {
			return nil, apiErr
		}
		if present {
			for key, value := range body {
				bag.values[key] = value
			}
		}
	}

	for _, param := range c.Params {
		bag.path[param.Key] = param.Value
	}
	return bag, nil
}

// decodeSingleJSONObject decodes raw as exactly one complete JSON object
// surrounded only by JSON whitespace. It returns present=false for an empty
// payload or one containing only JSON whitespace bytes; payloads of other
// Unicode whitespace are not empty and fall through to the decoder, which
// rejects them. A JSON null, array or other bare value, a truncated object,
// a second JSON value, or a stray closing bracket after the object
// (immediately or across whitespace) are all parameter errors.
//
// Decoder.More cannot be used to check completeness: it reports false for a
// dangling "}" or "]" because those are not value tokens. A second Decode
// must therefore return exactly io.EOF, which is true only once the object
// has ended and nothing but whitespace remains.
func decodeSingleJSONObject(raw []byte) (body map[string]any, present bool, apiErr *apiError) {
	if len(trimJSONWhitespace(raw)) == 0 {
		return nil, false, nil
	}
	decoder := json.NewDecoder(bytes.NewReader(raw))
	// UseNumber keeps every JSON number as its literal text so integer
	// fields (port) can be parsed exactly, without the float64 rounding
	// that json.Unmarshal would apply.
	decoder.UseNumber()
	var decoded map[string]any
	if err := decoder.Decode(&decoded); err != nil || decoded == nil {
		return nil, false, errInvalidParameter("request body must be a JSON object")
	}
	var trailing json.RawMessage
	if err := decoder.Decode(&trailing); err != io.EOF {
		return nil, false, errInvalidParameter("request body must be a single JSON object")
	}
	return decoded, true, nil
}

// readOptionalObjectBody reads a body that may be absent: no body or only
// the four JSON whitespace bytes yields present=false so the entry falls
// back to its query parameter rules, while every other non-empty payload
// (including other Unicode whitespace such as NBSP) is a parameter error.
func readOptionalObjectBody(c *gin.Context) (map[string]any, bool, *apiError) {
	if c.Request.Body == nil {
		return nil, false, nil
	}
	raw, err := io.ReadAll(c.Request.Body)
	if err != nil {
		return nil, false, errInvalidParameter("request body cannot be read")
	}
	return decodeSingleJSONObject(raw)
}

// readStrictObjectBody requires the body to be exactly one JSON object
// surrounded only by JSON whitespace. It is used by the batch entries whose
// contract forbids query-parameter merging: a missing/empty body, a JSON
// null, array or other bare value, a second JSON value, or a stray closing
// bracket after the object are all parameter errors, even when the first
// object carries complete, valid entries.
func readStrictObjectBody(c *gin.Context) (map[string]any, *apiError) {
	if c.Request.Body == nil {
		return nil, errInvalidParameter("request body must be a JSON object")
	}
	raw, err := io.ReadAll(c.Request.Body)
	if err != nil {
		return nil, errInvalidParameter("request body cannot be read")
	}
	body, present, apiErr := decodeSingleJSONObject(raw)
	if apiErr != nil {
		return nil, apiErr
	}
	if !present {
		return nil, errInvalidParameter("request body must be a JSON object")
	}
	return body, nil
}

// buildStrictObjectBag is a paramBag populated from exactly one JSON object:
// unlike buildParamBag it never reads query parameters, so a rejected or
// missing body field cannot be repaired through the URL. Path parameters are
// still recorded so path locators keep winning.
func buildStrictObjectBag(c *gin.Context) (*paramBag, *apiError) {
	body, apiErr := readStrictObjectBody(c)
	if apiErr != nil {
		return nil, apiErr
	}
	bag := &paramBag{
		values: make(map[string]any, len(body)),
		path:   make(map[string]any),
	}
	for key, value := range body {
		bag.values[key] = value
	}
	for _, param := range c.Params {
		bag.path[param.Key] = param.Value
	}
	return bag, nil
}

func (b *paramBag) get(keys []string) (any, bool) {
	for _, key := range keys {
		if value, ok := b.values[key]; ok {
			return value, true
		}
	}
	return nil, false
}

// locateText resolves one locator field (service name or instance id). A
// value carried by the route path always wins: a conflicting, empty or
// non-string value of the same field in the body or query string is ignored,
// and a blank path segment is a parameter error that cannot be filled from
// another source. Only when the route carries no such segment does the field
// fall back to the existing body/query lookup rules.
func (b *paramBag) locateText(pathKey string, keys []string, message string) (string, *apiError) {
	if raw, fromPath := b.path[pathKey]; fromPath {
		text := strings.TrimSpace(stringValue(raw))
		if text == "" {
			return "", errInvalidParameter(message)
		}
		return text, nil
	}
	return b.requiredText(keys, message)
}

// readJSONObject requires the request body to be a single JSON object. An
// empty body, a body of only JSON whitespace bytes, a JSON array or any
// non-object payload is a parameter error; other Unicode whitespace such as
// NBSP is likewise rejected by the parser. It is used by the batch entry
// points whose contract forbids merging query parameters or accepting a bare
// value.
func readJSONObject(c *gin.Context) (map[string]any, *apiError) {
	if c.Request.Body == nil {
		return nil, errInvalidParameter("request body must be a JSON object")
	}
	raw, err := io.ReadAll(c.Request.Body)
	if err != nil {
		return nil, errInvalidParameter("request body cannot be read")
	}
	if len(trimJSONWhitespace(raw)) == 0 {
		return nil, errInvalidParameter("request body must be a JSON object")
	}
	var body map[string]any
	if err := json.Unmarshal(raw, &body); err != nil || body == nil {
		return nil, errInvalidParameter("request body must be a JSON object")
	}
	return body, nil
}

func stringValue(value any) string {
	if text, ok := value.(string); ok {
		return text
	}
	return ""
}

// readHealthyInput accepts a new healthy state for one instance from either a
// JSON body field ("healthy": true|false) or the ?healthy=true|false query
// parameter. The JSON field wins when both carry it. JSON accepts only
// booleans, while the query parameter accepts only the lowercase text "true"
// or "false"; every other representation is a parameter error. As on every
// other entry, only an absent body or one made solely of the four JSON
// whitespace bytes falls back to the query parameter; other Unicode
// whitespace makes the body a parameter error.
func readHealthyInput(c *gin.Context) (bool, *apiError) {
	queryValue, queryPresent := c.GetQuery("healthy")

	if c.Request.Body != nil {
		raw, err := io.ReadAll(c.Request.Body)
		if err != nil {
			return false, errInvalidParameter("request body cannot be read")
		}
		if len(trimJSONWhitespace(raw)) > 0 {
			var body map[string]any
			if err := json.Unmarshal(raw, &body); err != nil || body == nil {
				return false, errInvalidParameter("request body must be a JSON object")
			}
			if value, present := body["healthy"]; present {
				healthy, ok := strictBoolValue(value)
				if !ok {
					return false, errInvalidParameter("healthy must be a boolean true or false")
				}
				return healthy, nil
			}
		}
	}

	if !queryPresent {
		return false, errInvalidParameter("healthy must be a boolean true or false")
	}
	switch queryValue {
	case "true":
		return true, nil
	case "false":
		return false, nil
	default:
		return false, errInvalidParameter("healthy must be a boolean true or false")
	}
}

// requiredText returns the trimmed text for the first matching key, or an error
// when the value is missing or blank.
func (b *paramBag) requiredText(keys []string, message string) (string, *apiError) {
	value, ok := b.get(keys)
	if !ok {
		return "", errInvalidParameter(message)
	}
	text := strings.TrimSpace(stringValue(value))
	if text == "" {
		return "", errInvalidParameter(message)
	}
	return text, nil
}

// positiveNumber accepts weights: only numbers strictly greater than zero.
func positiveNumber(value any) (float64, bool) {
	number, ok := toFloat(value)
	if !ok || math.IsNaN(number) || math.IsInf(number, 0) || number <= 0 {
		return 0, false
	}
	return number, true
}

// parsePortValue accepts a non-negative integer port number in the range
// [0, 9223372036854775807]. JSON numbers and numeric strings are parsed from
// their decimal text with exact integer semantics: values above 2^53 keep
// their exact value, fractional forms such as 8080.0 or 8.08e3 collapse to
// their integer value, and the int64 bound is enforced without rounding, so
// 9223372036854775808 is rejected instead of overflowing the conversion.
func parsePortValue(value any) (int64, bool) {
	switch typed := value.(type) {
	case json.Number:
		return parsePortText(typed.String())
	case string:
		return parsePortText(strings.TrimSpace(typed))
	case float64:
		// A float64 at or beyond 2^63 cannot be a valid port: the largest
		// exactly representable candidate below it is 2^63-1024, and the
		// int64 conversion of anything larger would overflow.
		if math.IsNaN(typed) || math.IsInf(typed, 0) || typed != math.Trunc(typed) ||
			typed < 0 || typed >= 9223372036854775808.0 {
			return 0, false
		}
		return int64(typed), true
	case int:
		return int64(typed), typed >= 0
	case int64:
		return typed, typed >= 0
	default:
		return 0, false
	}
}

// portNumberPattern is the decimal grammar a port may use: an integer or a
// fixed/scientific decimal with an optional sign.
var portNumberPattern = regexp.MustCompile(`^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)([eE][+-]?[0-9]+)?$`)

// parsePortText parses the exact integer value of a decimal number without
// going through float64. The mantissa is kept as a digit string and the
// exponent as a small int, so huge exponents are rejected by digit counting
// instead of materializing enormous integers.
func parsePortText(text string) (int64, bool) {
	// Fast path: a plain decimal integer, exact for the whole int64 range.
	if number, err := strconv.ParseInt(text, 10, 64); err == nil {
		return number, number >= 0
	}
	if !portNumberPattern.MatchString(text) {
		return 0, false
	}
	negative := strings.HasPrefix(text, "-")
	mantissa := strings.TrimLeft(text, "+-")
	exponent := 0
	if at := strings.IndexAny(mantissa, "eE"); at >= 0 {
		expText := mantissa[at+1:]
		mantissa = mantissa[:at]
		if digits := strings.TrimLeft(strings.TrimLeft(expText, "+-"), "0"); len(digits) > 6 {
			// |exponent| >= 10^6: the value is either far beyond the int64
			// bound or far below one; only an all-zero mantissa is still
			// exactly zero.
			if allZeroDigits(mantissa) {
				return 0, true
			}
			return 0, false
		}
		exponent, _ = strconv.Atoi(expText)
	}
	intPart, fracPart := mantissa, ""
	if at := strings.IndexByte(mantissa, '.'); at >= 0 {
		intPart, fracPart = mantissa[:at], mantissa[at+1:]
	}
	// value = digits * 10^k
	digits := intPart + fracPart
	k := exponent - len(fracPart)
	digits = strings.TrimLeft(digits, "0")
	for strings.HasSuffix(digits, "0") {
		digits = digits[:len(digits)-1]
		k++
	}
	if digits == "" {
		return 0, true // exact zero, in any form
	}
	if negative || k < 0 {
		// A negative port is out of range; a negative remaining exponent
		// leaves a fractional part, so the value is not an integer.
		return 0, false
	}
	if len(digits)+k > 19 {
		return 0, false
	}
	number, err := strconv.ParseInt(digits+strings.Repeat("0", k), 10, 64)
	if err != nil {
		return 0, false // 19 digits but beyond math.MaxInt64
	}
	return number, true
}

// allZeroDigits reports whether a mantissa (digits with an optional dot)
// denotes zero.
func allZeroDigits(mantissa string) bool {
	for _, r := range mantissa {
		if r != '0' && r != '.' {
			return false
		}
	}
	return true
}

// strictBoolValue accepts only JSON boolean true or false. Every other
// representation (text, numbers) is rejected so all implementations agree.
func strictBoolValue(value any) (bool, bool) {
	typed, ok := value.(bool)
	return typed, ok
}

func toFloat(value any) (float64, bool) {
	switch typed := value.(type) {
	case float64:
		return typed, true
	case int:
		return float64(typed), true
	case int64:
		return float64(typed), true
	case json.Number:
		number, err := typed.Float64()
		if err != nil {
			return 0, false
		}
		return number, true
	case string:
		number, err := strconv.ParseFloat(strings.TrimSpace(typed), 64)
		if err != nil {
			return 0, false
		}
		return number, true
	default:
		return 0, false
	}
}

func parseHealthValue(value any) (bool, bool) {
	switch typed := value.(type) {
	case bool:
		return typed, true
	case float64:
		switch typed {
		case 1:
			return true, true
		case 0:
			return false, true
		}
	case json.Number:
		if number, err := typed.Float64(); err == nil {
			switch number {
			case 1:
				return true, true
			case 0:
				return false, true
			}
		}
	case string:
		switch strings.ToLower(strings.TrimSpace(typed)) {
		case "healthy", "up", "on", "true", "1", "yes":
			return true, true
		case "unhealthy", "down", "off", "false", "0", "no":
			return false, true
		}
	}
	return false, false
}

// Accepted timestamps cover [0000-01-01T00:00:00Z, 10000-01-01T00:00:00Z)
// once converted to UTC: the lower bound is included, the upper bound is
// excluded. These are exactly the instants the RFC3339 storage format can
// write and read back, so anything outside could never round-trip.
var (
	minAcceptedTime = time.Date(0, 1, 1, 0, 0, 0, 0, time.UTC)
	maxAcceptedTime = time.Date(10000, 1, 1, 0, 0, 0, 0, time.UTC)
)

func inAcceptedTimeRange(t time.Time) bool {
	t = t.UTC()
	return !t.Before(minAcceptedTime) && t.Before(maxAcceptedTime)
}

func parseTimeValue(value any) (time.Time, bool) {
	switch typed := value.(type) {
	case string:
		text := strings.TrimSpace(typed)
		if text == "" {
			return time.Time{}, false
		}
		if number, err := strconv.ParseFloat(text, 64); err == nil {
			return unixTimeInRange(number)
		}
		for _, layout := range []string{time.RFC3339Nano, time.RFC3339, "2006-01-02T15:04:05", "2006-01-02 15:04:05"} {
			if parsed, err := time.Parse(layout, text); err == nil {
				if !inAcceptedTimeRange(parsed) {
					return time.Time{}, false
				}
				return parsed, true
			}
		}
	case float64:
		return unixTimeInRange(typed)
	case json.Number:
		number, err := typed.Float64()
		if err != nil {
			return time.Time{}, false
		}
		return unixTimeInRange(number)
	}
	return time.Time{}, false
}

// unixTimeInRange converts a Unix second count that lands inside the
// accepted range. The range check runs on the float itself, before any int64
// conversion, so non-finite values (NaN, Inf, Infinity with any sign) and
// out-of-range finite values are rejected instead of overflowing and
// wrapping back into a valid-looking date.
func unixTimeInRange(seconds float64) (time.Time, bool) {
	if math.IsNaN(seconds) || math.IsInf(seconds, 0) ||
		seconds < float64(minAcceptedTime.Unix()) || seconds >= float64(maxAcceptedTime.Unix()) {
		return time.Time{}, false
	}
	return unixTime(seconds), true
}

func unixTime(seconds float64) time.Time {
	whole := int64(seconds)
	fraction := seconds - float64(whole)
	return time.Unix(whole, int64(fraction*1e9)).UTC()
}

// parseTimeout accepts a number of seconds or a duration string such as "30s".
// A non-positive duration is reported as invalid by the caller.
func parseTimeout(value any) (time.Duration, bool) {
	switch typed := value.(type) {
	case float64:
		if math.IsNaN(typed) || math.IsInf(typed, 0) {
			return 0, false
		}
		return time.Duration(typed * float64(time.Second)), true
	case json.Number:
		number, err := typed.Float64()
		if err != nil || math.IsNaN(number) || math.IsInf(number, 0) {
			return 0, false
		}
		return time.Duration(number * float64(time.Second)), true
	case string:
		text := strings.TrimSpace(typed)
		if text == "" {
			return 0, false
		}
		if duration, err := time.ParseDuration(text); err == nil {
			return duration, true
		}
		if number, err := strconv.ParseFloat(text, 64); err == nil && !math.IsNaN(number) && !math.IsInf(number, 0) {
			return time.Duration(number * float64(time.Second)), true
		}
	}
	return 0, false
}

package api

import (
	"net/http"
	"regexp"
	"strings"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/service-discovery-api/internal/store"
)

var emptyServicePaths = []*regexp.Regexp{
	regexp.MustCompile(`^/api/v1/services/(/instances)?/?$`),
	regexp.MustCompile(`^/api/v1/services/(/instances/batch)/?$`),
	regexp.MustCompile(`^/api/v1/services/(/discover)/?$`),
	regexp.MustCompile(`^/api/v1/services/(/instances/[^/]+/heartbeat)/?$`),
	regexp.MustCompile(`^/api/v1/services/(/instances/weight)/?$`),
	regexp.MustCompile(`^/api/v1/services/(/instances/[^/]+/weight)/?$`),
	regexp.MustCompile(`^/api/v1/services/(/instances/health)/?$`),
	regexp.MustCompile(`^/api/v1/services/(/instances/[^/]+/health)/?$`),
	regexp.MustCompile(`^/api/v1/services/[^/]+/instances/(/health)/?$`),
	regexp.MustCompile(`^/api/v1/services/[^/]+/instances/(/weight)/?$`),
}

// Server wires the store to every public HTTP entry point.
type Server struct {
	store *store.Store
}

// NewRouter wires the public HTTP surface. The service contract in README.md
// describes the single-error-object shape every entry must keep.
func NewRouter(st *store.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	router.Use(gin.Recovery())

	server := &Server{store: st}

	router.GET("/healthz", func(c *gin.Context) {
		if err := st.Ping(); err != nil {
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": gin.H{"code": "storage_unavailable", "message": "database is not available"}})
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	})

	// Registration and update share one upsert entry; repeated registration
	// of the same (service, instance) pair overwrites the current record.
	router.POST("/api/v1/services/:serviceName/instances", server.handleUpsert)
	router.PUT("/api/v1/services/:serviceName/instances/:instanceId", server.handleUpsert)
	router.POST("/api/v1/register", server.handleUpsert)
	router.POST("/api/v1/instances", server.handleUpsert)
	router.PUT("/api/v1/instances", server.handleUpsert)

	// Batch registration applies several upserts of one service in one
	// atomic request. The path entry takes its service name from the path;
	// the register entry takes it from the body's service_name field.
	router.POST("/api/v1/services/:serviceName/instances/batch", server.handleBatchUpsertByPath)
	router.POST("/api/v1/register/batch", server.handleBatchUpsertByBody)

	// Public instance query entries.
	// Read-only overview of every service that still has instance records.
	router.GET("/api/v1/services", server.handleListServices)
	router.GET("/api/v1/services/:serviceName/instances", server.handleListInstances)
	router.GET("/api/v1/services/:serviceName/instances/:instanceId", server.handleGetInstance)
	router.GET("/api/v1/services/:serviceName/instances/:instanceId/health", server.handleGetHealth)
	router.GET("/api/v1/services/:serviceName/instances/:instanceId/weight", server.handleGetWeight)
	router.GET("/api/v1/services/:serviceName/instances/:instanceId/heartbeat", server.handleGetHeartbeat)
	router.GET("/api/v1/instances", server.handleGetInstance)
	router.GET("/api/v1/instances/health", server.handleGetHealth)
	router.GET("/api/v1/instances/weight", server.handleGetWeight)
	router.GET("/api/v1/instances/heartbeat", server.handleGetHeartbeat)
	router.GET("/api/v1/list", server.handleListInstances)

	// Instance deletion.
	router.DELETE("/api/v1/services/:serviceName/instances/:instanceId", server.handleDelete)
	router.POST("/api/v1/services/:serviceName/instances/:instanceId/delete", server.handleDelete)
	router.DELETE("/api/v1/instances", server.handleDelete)
	router.POST("/api/v1/deregister", server.handleDelete)

	// Heartbeat renewal: only heartbeat_at is replaced; the caller never
	// resubmits address, port, health state or weight.
	router.POST("/api/v1/services/:serviceName/instances/:instanceId/heartbeat", server.handleHeartbeat)
	router.POST("/api/v1/heartbeat", server.handleBatchHeartbeat)

	// Weight-only updates replace just weight; address, port, health state
	// and heartbeat time keep their current values, and the upsert
	// overwrite semantics stay unchanged.
	router.PUT("/api/v1/services/:serviceName/instances/weight", server.handleBatchUpdateWeight)
	router.PUT("/api/v1/services/:serviceName/instances/:instanceId/weight", server.handleUpdateWeight)

	// Health-state-only updates replace just the healthy flag; address,
	// port, weight and heartbeat time keep their current values, no missing
	// instance is created and no heartbeat is renewed.
	router.PUT("/api/v1/services/:serviceName/instances/health", server.handleBatchUpdateHealth)
	router.PUT("/api/v1/services/:serviceName/instances/:instanceId/health", server.handleUpdateHealth)

	// Discovery of healthy instances with heartbeat-lost removal.
	router.GET("/api/v1/services/:serviceName/discover", server.handleDiscover)
	router.GET("/api/v1/discover", server.handleDiscover)
	router.POST("/api/v1/services/:serviceName/discover", server.handleDiscover)
	router.POST("/api/v1/discover", server.handleDiscover)
	router.POST("/api/v1/discover/batch", server.handleBatchDiscover)

	// Standalone lost-instance cleanup across one or all services.
	router.POST("/api/v1/cleanup", server.handleCleanup)

	router.NoRoute(func(c *gin.Context) {
		// An empty final path segment (e.g. /api/v1/services//instances)
		// carries an empty service name and must be a parameter error.
		for _, pattern := range emptyServicePaths {
			if pattern.MatchString(c.Request.URL.Path) {
				switch {
				case strings.HasSuffix(c.Request.URL.Path, "/discover"):
					c.Params = gin.Params{{Key: "serviceName", Value: ""}}
					server.handleDiscover(c)
				case strings.HasSuffix(c.Request.URL.Path, "/heartbeat"):
					c.Params = gin.Params{{Key: "serviceName", Value: ""}}
					server.handleHeartbeat(c)
				case strings.HasSuffix(c.Request.URL.Path, "/instances/batch"):
					c.Params = gin.Params{{Key: "serviceName", Value: ""}}
					server.handleBatchUpsertByPath(c)
				case c.Request.Method == http.MethodPut && strings.HasSuffix(c.Request.URL.Path, "/instances/weight"):
					c.Params = gin.Params{{Key: "serviceName", Value: ""}}
					server.handleBatchUpdateWeight(c)
				case c.Request.Method == http.MethodPut && strings.HasSuffix(c.Request.URL.Path, "/instances/health"):
					c.Params = gin.Params{{Key: "serviceName", Value: ""}}
					server.handleBatchUpdateHealth(c)
				case c.Request.Method == http.MethodPut && strings.HasSuffix(c.Request.URL.Path, "/health"):
					emptyInstance := strings.HasSuffix(c.Request.URL.Path, "//health")
					if emptyInstance {
						c.Params = gin.Params{
							{Key: "serviceName", Value: ""},
							{Key: "instanceId", Value: ""},
						}
					} else {
						c.Params = gin.Params{{Key: "serviceName", Value: ""}}
					}
					server.handleUpdateHealth(c)
				case c.Request.Method == http.MethodPut && strings.HasSuffix(c.Request.URL.Path, "/weight"):
					emptyInstance := strings.HasSuffix(c.Request.URL.Path, "//weight")
					if emptyInstance {
						c.Params = gin.Params{
							{Key: "serviceName", Value: ""},
							{Key: "instanceId", Value: ""},
						}
					} else {
						c.Params = gin.Params{{Key: "serviceName", Value: ""}}
					}
					server.handleUpdateWeight(c)
				case c.Request.Method == http.MethodDelete || (c.Request.Method == http.MethodPost && strings.HasSuffix(c.Request.URL.Path, "/delete")):
					c.Params = gin.Params{{Key: "serviceName", Value: ""}}
					server.handleDelete(c)
				case c.Request.Method == http.MethodPost:
