	t.Helper()
	rows, err := st.ListAllInstances()
	if err != nil {
		t.Fatalf("list all: %v", err)
	}
	sort.Slice(rows, func(i, j int) bool {
		if rows[i].ServiceName != rows[j].ServiceName {
			return rows[i].ServiceName < rows[j].ServiceName
